/* eslint-disable @typescript-eslint/naming-convention */
import { ISellerModel } from '../person/SellerModel';
import { IProductImageModel, IProductVideoModel, IProductDesignViewModel, IFurtherDetailViewModel } from './AddOrUpdateProductModel';
import { IProductTagModel } from './ProductFilterModel';

export interface IProductModel {

  id: number;
  name: string;
  price: number;
  offPrice: number;
  viewCount: number;
  shortDescription: string;
  description: string;
  imageName: string;
  isActive: boolean;
  isEdited: boolean;
  isExists: boolean;
  isSpecial: boolean;
  createDate: Date;
  lastUpdateDate: Date;
  isUsed: boolean;
  categoryIds: number[];
  seller: ISellerModel;
  isCallOnly: boolean;

  productImages: IProductImageModel[];
  productVideos: IProductVideoModel[];
  productDesigns: IProductDesignViewModel[];
  furtherDetails: IFurtherDetailViewModel[];
}

export class ProductModel implements IProductModel {

  id: number;
  name: string;
  price: number;
  offPrice: number;
  viewCount: number;
  shortDescription: string;
  description: string;
  imageName: string;
  isActive: boolean;
  isEdited: boolean;
  isExists: boolean;
  isSpecial: boolean;
  createDate: Date;
  lastUpdateDate: Date;
  isUsed: boolean;
  categoryIds: number[];
  seller: ISellerModel;
  isCallOnly: boolean;

  productImages: IProductImageModel[];
  productVideos: IProductVideoModel[];
  productDesigns: IProductDesignViewModel[];
  furtherDetails: IFurtherDetailViewModel[];

  constructor(
    id: number,
    name: string,
    Price: number,
    OffPrice: number,
    ViewCount: number,
    ShortDescription: string,
    Description: string,
    imageName: string,
    IsExists: boolean,
    IsSpecial: boolean,
    CreateDate: Date,
    LastUpdateDate: Date,
    IsUsed: boolean,
    CategoryIds: number[]) {

    this.id = id;
    this.name = name;
    this.price = Price;
    this.offPrice = OffPrice;
    this.viewCount = ViewCount;
    this.shortDescription = ShortDescription;
    this.description = Description;
    this.imageName = imageName;
    this.isExists = IsExists;
    this.isSpecial = IsSpecial;
    this.createDate = CreateDate;
    this.lastUpdateDate = LastUpdateDate;
    this.isUsed = IsUsed;
    this.categoryIds = CategoryIds;
  }
}

export interface IUserProductRateViewModel {

    id: number;
    buyerUserId: number;
    productId: number;
    q1Rate: number;
    q2Rate: number;
    q3Rate: number;
    q4Rate: number;
    description: string;
    createDate: Date;
    lastUpdateDate: Date;
}

export class UserProductRateViewModel implements IUserProductRateViewModel {

  id: number;
  buyerUserId: number;
  productId: number;
  q1Rate: number;
  q2Rate: number;
  q3Rate: number;
  q4Rate: number;
  description: string;
  createDate: Date;
  lastUpdateDate: Date;

    constructor(
      id: number,
      buyerUserId: number,
      productId: number,
      q1Rate: number,
      q2Rate: number,
      q3Rate: number,
      q4Rate: number,
      description?: string,
      createDate?: Date,
      lastUpdateDate?: Date
    ) {

        this.id = id;
        this.buyerUserId = buyerUserId;
        this.productId = productId;
        this.q1Rate = q1Rate;
        this.q2Rate = q2Rate;
        this.q3Rate = q3Rate;
        this.q4Rate = q4Rate;
        this.description = description;
        this.createDate = createDate;
        this.lastUpdateDate = lastUpdateDate;
    }
}

export interface IProductLikeModel {

  like: number;
  dissLike: number;
}

export class ProductLikeModel implements IProductLikeModel {

  like: number;
  dissLike: number;

  constructor(
    like: number,
    dissLike: number
  ) {

    this.like = like;
    this.dissLike = dissLike;
  }
}

export interface IAddOrUpdateProductTagModel {

  productId: number;
  productTags: IProductTagModel[];
}

export class AddOrUpdateProductTagModel implements IAddOrUpdateProductTagModel {

  productId: number;
  productTags: IProductTagModel[];

  constructor(
    productId: number,
    productTags: IProductTagModel[]
  ) {

    this.productId = productId;
    this.productTags = productTags;
  }
}

export interface IProductListModel {

  id: number;
  name: string;
}

export class ProductListModel implements IProductListModel {

  id: number;
  name: string;

  constructor(
      id: number,
      name: string
  ) {
      this.id = id;
      this.name = name;
  }
}
