import { Component, OnInit } from '@angular/core';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { ProductService } from '../../../../../data/service/product/product.service';
import { IProductFilterModel, ProductFilterModel, IProductTagModel, ProductTagModel } from '../../../../../data/model/product/ProductFilterModel';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { AddOrUpdateProductTagModel } from '../../../../../data/model/product/ProductModel';

@Component({
  selector: 'app-product-tag',
  templateUrl: './product-tag.component.html',
  styleUrls: ['./product-tag.component.scss']
})
export class ProductTagComponent implements OnInit {

  selectedCourseId = 0;
  filteredCourses: IProductFilterModel;
  isSelected = false;
  searchTitle = '';
  selectedCategory = 'add';
  addList: string[] = [];
  editList: IProductTagModel[] = [];
  tagName = '';
  form: FormGroup;

  constructor(
    private fb: FormBuilder,
    private courseService: ProductService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      id: ['', [Validators.required, Validators.min(1)]],
      tag: ['', [Validators.required, Validators.minLength(2), Validators.maxLength(2000)]]
    });

    let filter: IProductFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;
      const startPrice = params.startPrice ? params.startPrice : null;
      const endPrice = params.endPrice ? params.endPrice : null;
      const categoryIds = params.categoryIds ? params.categoryIds : [];
      const sortId = params.sortId ? params.sortId : 4;

      filter = new ProductFilterModel(false, page, take, title);

      this.filteredCourses = filter;

      SharedIonic.loading(this.loadingController);

      this.courseService.GetAdminProductsByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredCourses = res.data;
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  onTagSelected(index: string | number) {

    let model: IProductTagModel = this.editList[index];

    this.form.setValue({
      id: model.id,
      tag: model.name
    });
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به درج هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAddTags();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdateTags();
          }
        }
      ]
    });

    await alert.present();
  }

  onRemoveEditTag(index: string | number) {

    let model: IProductTagModel = this.editList[index];

    SharedIonic.loading(this.loadingController);

    this.courseService.RemoveProductTag(model.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.getTagsByCourseId(this.selectedCourseId);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onCancel() {
    this.isSelected = false;

    this.addList = [];
    this.editList = [];
    this.tagName = '';
  }

  onAddTag() {

    if (this.tagName === '') {

      return;
    }

    this.addList.push(this.tagName);
    this.tagName = '';
  }

  onUpdateTags() {

    if (!this.form.valid) {
      return;
    }

    let list: IProductTagModel[] = [];

    this.editList.forEach(tag => {
      if (+this.form.value.id === +tag.id) {
        list.push(new ProductTagModel(tag.id, this.form.value.tag));
      } else {
        list.push(new ProductTagModel(tag.id, tag.name));
      }
    });

    SharedIonic.loading(this.loadingController);

    this.courseService.AddOrUpdateProductTag(
      new AddOrUpdateProductTagModel(this.selectedCourseId, list)
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.tagName = '';
          this.addList = [];
          list = [];
          this.getTagsByCourseId(this.selectedCourseId);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onAddTags() {

    if (this.addList.length === 0) {

      return;
    }

    let list: IProductTagModel[] = [];

    this.addList.forEach(tag => {
      list.push(new ProductTagModel(0, tag));
    });

    SharedIonic.loading(this.loadingController);

    this.courseService.AddOrUpdateProductTag(
      new AddOrUpdateProductTagModel(this.selectedCourseId, list)
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.tagName = '';
          this.addList = [];
          list = [];
          this.getTagsByCourseId(this.selectedCourseId);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onRemoveAddTag(index: number | string) {

    this.addList.splice(+index, 1);
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredCourses.startPage == null) {
      return;
    }
    if (this.filteredCourses.pageId > this.filteredCourses.startPage && +this.filteredCourses.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredCourses.title = this.searchTitle;

    this.router
      .navigate(
        ['AdminPanel', 'ProductTag'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredCourses.takeEntity ? this.filteredCourses.takeEntity : null,
            title: this.filteredCourses.title ? this.filteredCourses.title : null
          }
        });
  }

  onDelete(): void {

    // SharedIonic.loading(this.loadingController);

    // this.articleService.DeleteArticleById(+this.selectedArticleId).subscribe(
    //   res => {
    //     SharedIonic.dismissLoading(this.loadingController);
    //     if (GResponse.SuccessStatus === res.status) {
    //       SharedIonic.successToast(this.toastController);
    //       this.setQueryParams(1);
    //     } else {
    //       SharedIonic.unSuccessToast(this.toastController);
    //     }
    //   },
    //   err => {
    //     SharedIonic.dismissLoading(this.loadingController);
    //     SharedIonic.unSuccessToast(this.toastController);
    //   }
    // );
  }

  async presentAlertConfirm(index: number | string) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onRemoveAddTag(index);
          }
        }
      ]
    });

    await alert.present();
  }

  async presentRemoveAlertConfirm(index: number | string) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onRemoveEditTag(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onSelectItem(id: string | number) {

    this.selectedCourseId = +id;
    this.isSelected = true;

    this.getTagsByCourseId(id);
  }

  getTagsByCourseId(id: string | number) {

    SharedIonic.loading(this.loadingController);

    this.courseService.GetProductTags(+id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          this.editList = res.data;
          this.form.setValue({
            id: 0,
            tag: ''
          });
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }
}
